def _get_output_config(method, estimator, global_config):
    # Mocked _get_output_config
    est_sklearn_output_config = getattr(estimator, "_sklearn_output_config", {})
    if method in est_sklearn_output_config:
        dense_config = est_sklearn_output_config[method]
    else:
        dense_config = global_config[f"{method}_output"]

    if dense_config not in {"default", "pandas"}:
        raise ValueError(
            f"output config must be 'default' or 'pandas' got {dense_config}"
        )

    dtypes_config = est_sklearn_output_config.get("dtypes")
    if dtypes_config is None:
        dtypes_config = global_config.get(f"{method}_output_dtypes")

    return {"dense": dense_config, "dtypes": dtypes_config}

